from z3 import *

n = 6
X = [[Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]

s = Solver()

# Domain
for i in range(n):
    for j in range(n):
        s.add(X[i][j] >= 0, X[i][j] < n)

# Latin square
for i in range(n):
    s.add(Distinct(X[i]))
for j in range(n):
    s.add(Distinct([X[i][j] for i in range(n)]))

# Idempotent
for i in range(n):
    s.add(X[i][i] == i)

# QG3
for i in range(n):
    for j in range(n):
        # x[ x[i][j] ][ x[j][i] ] = i
        # We can express this using a function or nested indexing.
        # Since n is small, we can use Or over all possible values of x[i][j] and x[j][i]
        # Or better, use Z3's array or just simple implications.

        u = X[i][j]
        v = X[j][i]

        # We want X[u][v] == i
        for u_val in range(n):
            for v_val in range(n):
                s.add(Implies(And(u == u_val, v == v_val), X[u_val][v_val] == i))

if s.check() == sat:
    m = s.model()
    res = []
    for i in range(n):
        for j in range(n):
            res.append(m.evaluate(X[i][j]).as_long())
    print("SAT")
    print(res)
else:
    print("UNSAT")

def solve_qg3(n):
    # Backtracking solver for QG3
    # x[i][j]
    grid = [[-1]*n for _ in range(n)]

    # Idempotent
    for i in range(n):
        grid[i][i] = i

    row_used = [[False]*n for _ in range(n)]
    col_used = [[False]*n for _ in range(n)]

    for i in range(n):
        row_used[i][i] = True
        col_used[i][i] = True

    def check_qg3(r, c, val):
        # We are setting grid[r][c] = val
        # We need to check if any QG3 constraints are violated
        # QG3: grid[grid[i][j]][grid[j][i]] == i

        # 1. i=r, j=c: grid[val][grid[c][r]] == r
        if grid[c][r] != -1:
            v2 = grid[c][r]
            if grid[val][v2] != -1 and grid[val][v2] != r:
                return False
            if grid[val][v2] == -1:
                # If we were to set it, would it violate row/col?
                if row_used[val][r] or col_used[v2][r]:
                    return False

        # 2. i=c, j=r: grid[grid[c][r]][val] == c
        if grid[c][r] != -1:
            v1 = grid[c][r]
            if grid[v1][val] != -1 and grid[v1][val] != c:
                return False
            if grid[v1][val] == -1:
                if row_used[v1][c] or col_used[val][c]:
                    return False

        # 3. grid[r][x] == c and grid[x][r] == y -> grid[c][y] == r
        # This is getting complicated, let's just do a full check of fully assigned pairs
        for i in range(n):
            for j in range(n):
                if grid[i][j] != -1 and grid[j][i] != -1:
                    u = grid[i][j]
                    v = grid[j][i]
                    if grid[u][v] != -1 and grid[u][v] != i:
                        return False
        return True

    def solve(cell):
        if cell == n*n:
            return True
        r = cell // n
        c = cell % n
        if grid[r][c] != -1:
            return solve(cell + 1)

        for val in range(n):
            if not row_used[r][val] and not col_used[c][val]:
                grid[r][c] = val
                row_used[r][val] = True
                col_used[c][val] = True

                if check_qg3(r, c, val):
                    if solve(cell + 1):
                        return True

                grid[r][c] = -1
                row_used[r][val] = False
                col_used[c][val] = False
        return False

    if solve(0):
        return grid
    return None

